import{_ as a,C as d,o as h,c as i,a3 as e,E as o}from"./chunks/framework.Ba39LDvt.js";const p=JSON.parse('{"title":"AI 硬件自学","description":"连接高效深度学习、CUDA、DNN 加速器与大模型系统，建立正确性和性能证据。","frontmatter":{"title":"AI 硬件自学","description":"连接高效深度学习、CUDA、DNN 加速器与大模型系统，建立正确性和性能证据。"},"headers":[],"relativePath":"self-learning/ai-hardware.md","filePath":"self-learning/ai-hardware.md","lastUpdated":1795513256000}'),n={name:"self-learning/ai-hardware.md"};function l(s,t,c,f,b,_){const r=d("CourseTable");return h(),i("div",null,[t[0]||(t[0]=e('<h1 id="ai-硬件自学" tabindex="-1">AI 硬件自学 <a class="header-anchor" href="#ai-硬件自学" aria-label="Permalink to &quot;AI 硬件自学&quot;">​</a></h1><p>AI 硬件需要同时理解模型在算什么、数据在哪里移动、硬件怎样执行。建议先学矩阵乘法和存储层次，再区分两条路线：<strong>在现有 GPU 上优化程序</strong>，与<strong>设计新的加速器或微架构</strong>。两者互相帮助，但 CUDA 跑得快不能直接证明某个 RTL 设计更好。方向全景见 <a href="/shanghaitech-ic-wiki-dev.github.io/research/ai-hardware">AI 硬件研究</a>。</p><h2 id="入门-模型、数据和计算成本" tabindex="-1">入门：模型、数据和计算成本 <a class="header-anchor" href="#入门-模型、数据和计算成本" aria-label="Permalink to &quot;入门：模型、数据和计算成本&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>难度</th><th>说明</th></tr></thead><tbody><tr><td><a href="https://efficientml.ai/" target="_blank" rel="noreferrer">MIT 6.5940 / EfficientML</a></td><td>高效 AI 公开课入口</td><td>入门—进阶</td><td>覆盖 TinyML、高效 AI 计算相关主题；按学期查看量化、压缩与部署材料</td></tr><tr><td>Sze、Chen、Yang、Emer《Efficient Processing of Deep Neural Networks》</td><td>教材与教程</td><td>进阶</td><td>学习数据流、存储层次、稀疏与能耗；相关资源可从 <a href="https://eems.mit.edu/" target="_blank" rel="noreferrer">MIT EEMS</a> 进入</td></tr><tr><td><a href="https://pytorch.org/" target="_blank" rel="noreferrer">PyTorch</a></td><td>深度学习框架</td><td>入门—进阶</td><td>能实现、检查并测量一个小网络，比只调用训练脚本更重要</td></tr><tr><td><a href="https://developer.nvidia.com/cuda-zone" target="_blank" rel="noreferrer">NVIDIA CUDA</a></td><td>并行编程与官方文档</td><td>入门—进阶</td><td>从线程索引、内存层次、同步和错误检查开始，而非先追求极限优化</td></tr></tbody></table><p>先会计算一个矩阵乘法或卷积的运算量、参数量与中间激活大小。明确数据类型、批大小、精度指标和输入形状；峰值 TOPS 不能直接换算成应用吞吐，模型变小也不保证延迟按比例下降。定量思路可结合 <a href="/shanghaitech-ic-wiki-dev.github.io/self-learning/architecture">体系结构自学</a> 的 Roofline 学习。</p><h2 id="进阶-加速器和大模型系统" tabindex="-1">进阶：加速器和大模型系统 <a class="header-anchor" href="#进阶-加速器和大模型系统" aria-label="Permalink to &quot;进阶：加速器和大模型系统&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>难度</th><th>说明</th></tr></thead><tbody><tr><td><a href="https://cs217.stanford.edu/" target="_blank" rel="noreferrer">Stanford CS217</a></td><td>机器学习硬件加速器课程</td><td>进阶</td><td>关注并行性、局部性、低精度、数据流和系统级权衡；实践方式随学期变化</td></tr><tr><td><a href="https://cs336.stanford.edu/" target="_blank" rel="noreferrer">Stanford CS336</a></td><td>从零构建语言模型课程</td><td>进阶—深入</td><td>训练、资源核算、GPU 优化与分布式系统；需要 Python、深度学习和系统基础，不是 HDL 入门课</td></tr><tr><td>《Programming Massively Parallel Processors》</td><td>CUDA 教材</td><td>进阶</td><td>从并行模式学习矩阵乘法、归约和内存优化，结合当前 CUDA 文档使用</td></tr><tr><td><a href="https://github.com/NVlabs/timeloop" target="_blank" rel="noreferrer">Timeloop</a>、<a href="https://accelergy.mit.edu/" target="_blank" rel="noreferrer">Accelergy</a></td><td>加速器建模与能耗估计</td><td>进阶—深入</td><td>探索映射、数据复用与存储层次；结果是模型估计，须说明配置与边界</td></tr><tr><td><a href="https://github.com/ucb-bar/gemmini" target="_blank" rel="noreferrer">Gemmini</a></td><td>开源矩阵加速器生成器</td><td>进阶—深入</td><td>适合研究阵列、片上存储与软硬件接口，先理解配套系统及运行流程</td></tr><tr><td><a href="https://nvdla.org/" target="_blank" rel="noreferrer">NVDLA</a></td><td>开源深度学习推理加速器</td><td>进阶—深入</td><td>阅读模块划分、数据通路与软件接口，按官方支持的工作负载和平台使用</td></tr></tbody></table><p>阅读加速器论文时，重点比较外存流量、片上容量、利用率和支持的运算集合。不同工艺、频率、精度、批大小和模型准确率下的数字，不能直接排一个“性能榜”。使用模拟器或高层模型时，也不能将预测能耗表述为芯片实测。</p><h2 id="实践-先正确-再解释性能" tabindex="-1">实践：先正确，再解释性能 <a class="header-anchor" href="#实践-先正确-再解释性能" aria-label="Permalink to &quot;实践：先正确，再解释性能&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>难度</th><th>说明</th></tr></thead><tbody><tr><td>CUDA vector add / SAXPY</td><td>最小编程练习</td><td>入门</td><td>写边界检查，对照 CPU 参考结果，处理非整倍数长度</td></tr><tr><td>naive 与 tiled matmul</td><td>性能实验</td><td>进阶</td><td>固定输入和数据类型，比较数据复用与内存访问，不只比较代码长度</td></tr><tr><td>reduction 与同步实验</td><td>并行正确性实验</td><td>进阶</td><td>理解线程块独立性、归约顺序和浮点误差，不以偶然输出正确作为证明</td></tr><tr><td><a href="https://developer.nvidia.com/tools-overview" target="_blank" rel="noreferrer">Nsight 工具入口</a></td><td>性能分析工具</td><td>进阶</td><td>用时间线定位瓶颈，再用内核指标解释访存、同步或资源限制</td></tr><tr><td>Gemmini 小规模映射实验</td><td>加速器项目</td><td>深入</td><td>固定矩阵和数值格式，比较分块、数据流与存储开销，保存参考结果</td></tr></tbody></table><p>可按四个学习块推进：线程与索引、内存与分块、同步与归约、完整小项目。每块只保留一个主要变量。GPU 计时需要预热和正确同步，区分内核时间、传输时间与端到端时间；报告设备、软件版本和统计方法。浮点对比应先确定合理误差标准，不因失败而临时放宽标准。</p><h2 id="与上科大课程配合" tabindex="-1">与上科大课程配合 <a class="header-anchor" href="#与上科大课程配合" aria-label="Permalink to &quot;与上科大课程配合&quot;">​</a></h2>',12)),o(r,{codes:"EE219,CS290U,CS290W"}),t[1]||(t[1]=e('<p><a href="/shanghaitech-ic-wiki-dev.github.io/courses/ee219">EE219</a> 与加速器和系统思维相连接；<a href="/shanghaitech-ic-wiki-dev.github.io/courses/cs290u">CS290U</a> 及硬件部署相关课程可与模型工程实践配合。具体实验、工具和先修要求以当学期大纲为准。本文实践顺序参考维护者往届 CUDA 自学笔记，仅作为可裁剪建议，不承诺固定周数即可完成。</p><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><ul><li><a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Courses/SIST_2026-2027_Courses.htm" target="_blank" rel="noreferrer">上科大信息学院 2026–2027 学年开课计划</a>。</li><li>MIT 6.5940、Stanford CS217 / CS336 与开源项目的官方入口见上表。</li></ul>',3))])}const g=a(n,[["render",l]]);export{p as __pageData,g as default};
